import { config } from "../config";
import { db } from "../db/client";
import type { Upload, UploadStatus } from "../types";
import { backoffDelay } from "../util/retry";
import type { IngestErrorParams } from "./errors";

/**
 * Import jobs live in Postgres (table import_jobs), one per upload. Workers
 * claim them with FOR UPDATE SKIP LOCKED, so any number of processes can poll.
 */

export interface ImportJob {
  id: string;
  /** Includes the attempt currently running. */
  attempts: number;
  upload: Upload;
}

export interface NewUpload {
  id: string;
  accountId: string;
  userId: string;
  key: string;
  filename: string;
  sizeBytes: number;
}

export interface JobFailure {
  message: string;
  key?: string;
  params?: IngestErrorParams;
}

interface UploadRecord {
  id: string;
  account_id: string;
  user_id: string;
  storage_key: string;
  filename: string;
  size_bytes: number;
  status: UploadStatus;
  default_currency: string;
  error_key: string | null;
  error_params: IngestErrorParams | null;
  inserted_count: number | null;
  duplicate_count: number | null;
  created_at: Date;
  finished_at: Date | null;
}

const UPLOAD_COLUMNS = `u.id, u.account_id, u.user_id, u.storage_key, u.filename, u.size_bytes, u.status,
  a.default_currency, u.error_key, u.error_params, u.inserted_count, u.duplicate_count,
  u.created_at, u.finished_at`;

function toUpload(row: UploadRecord): Upload {
  return {
    id: row.id,
    accountId: row.account_id,
    userId: row.user_id,
    key: row.storage_key,
    filename: row.filename,
    sizeBytes: row.size_bytes,
    status: row.status,
    defaultCurrency: row.default_currency,
    errorKey: row.error_key,
    errorParams: row.error_params,
    insertedCount: row.inserted_count,
    duplicateCount: row.duplicate_count,
    createdAt: row.created_at,
    finishedAt: row.finished_at,
  };
}

export async function createUploadWithJob(input: NewUpload): Promise<void> {
  await db.tx(async (q) => {
    await q.query(
      `INSERT INTO uploads (id, account_id, user_id, storage_key, filename, size_bytes)
       VALUES ($1, $2, $3, $4, $5, $6)`,
      [input.id, input.accountId, input.userId, input.key, input.filename, input.sizeBytes],
    );
    await q.query("INSERT INTO import_jobs (upload_id) VALUES ($1)", [input.id]);
  });
}

export async function findUpload(id: string, userId: string): Promise<Upload | null> {
  const row = await db.maybeOne<UploadRecord>(
    `SELECT ${UPLOAD_COLUMNS} FROM uploads u JOIN accounts a ON a.id = u.account_id
      WHERE u.id = $1 AND u.user_id = $2`,
    [id, userId],
  );
  return row ? toUpload(row) : null;
}

export async function claimNext(): Promise<ImportJob | null> {
  return db.tx(async (q) => {
    const [job] = await q.query<{ id: string; attempts: number; upload_id: string }>(
      `SELECT id, attempts, upload_id FROM import_jobs
        WHERE status = 'pending' AND run_after <= now()
        ORDER BY run_after
        FOR UPDATE SKIP LOCKED
        LIMIT 1`,
    );
    if (!job) return null;

    await q.query("UPDATE import_jobs SET status = 'running', attempts = attempts + 1 WHERE id = $1", [job.id]);
    const [upload] = await q.query<UploadRecord>(
      `UPDATE uploads u SET status = 'importing' FROM accounts a
        WHERE u.id = $1 AND a.id = u.account_id
        RETURNING ${UPLOAD_COLUMNS}`,
      [job.upload_id],
    );
    return { id: job.id, attempts: job.attempts + 1, upload: toUpload(upload) };
  });
}

export async function completeJob(job: ImportJob, counts: { inserted: number; duplicates: number }): Promise<void> {
  await db.tx(async (q) => {
    await q.query("UPDATE import_jobs SET status = 'done', last_error = NULL WHERE id = $1", [job.id]);
    await q.query(
      `UPDATE uploads SET status = 'imported', inserted_count = $2, duplicate_count = $3, finished_at = now()
        WHERE id = $1`,
      [job.upload.id, counts.inserted, counts.duplicates],
    );
  });
}

/**
 * Reschedules the job with backoff, or marks it (and its upload) failed when it
 * is not retryable or has used all its attempts. Returns true when final.
 */
export async function failJob(job: ImportJob, failure: JobFailure, retryable: boolean): Promise<boolean> {
  const final = !retryable || job.attempts >= config.queue.maxAttempts;

  await db.tx(async (q) => {
    if (final) {
      await q.query("UPDATE import_jobs SET status = 'failed', last_error = $2 WHERE id = $1", [
        job.id,
        failure.message,
      ]);
      await q.query(
        `UPDATE uploads SET status = 'failed', error_key = $2, error_params = $3, finished_at = now()
          WHERE id = $1`,
        [job.upload.id, failure.key ?? null, failure.params ?? null],
      );
      return;
    }
    const delayMs = backoffDelay(job.attempts, 5_000, 10 * 60_000);
    await q.query(
      `UPDATE import_jobs SET status = 'pending', last_error = $2, run_after = now() + $3 * interval '1 millisecond'
        WHERE id = $1`,
      [job.id, failure.message, delayMs],
    );
    await q.query("UPDATE uploads SET status = 'pending' WHERE id = $1", [job.upload.id]);
  });

  return final;
}

export async function listFailedUploadsBefore(cutoff: Date, limit = 500): Promise<Pick<Upload, "id" | "key">[]> {
  const rows = await db.query<{ id: string; storage_key: string }>(
    "SELECT id, storage_key FROM uploads WHERE status = 'failed' AND finished_at < $1 ORDER BY finished_at LIMIT $2",
    [cutoff, limit],
  );
  return rows.map((row) => ({ id: row.id, key: row.storage_key }));
}

export async function markUploadPurged(id: string): Promise<void> {
  await db.query("UPDATE uploads SET status = 'purged' WHERE id = $1", [id]);
}

/** Runnable jobs only; finished and failed jobs do not count. */
export async function queueDepth(): Promise<number> {
  const row = await db.one<{ count: number }>(
    "SELECT count(*)::int AS count FROM import_jobs WHERE status IN ('pending', 'running')",
  );
  return row.count;
}


src/db/repos/reportRepo.ts
import type { Report, ReportSchedule } from "../../types";
import { db } from "../client";

interface ReportRecord {
  id: string;
  user_id: string;
  account_id: string;
  name: string;
  date_from: string;
  date_to: string;
  categories: string[];
  schedule: ReportSchedule | null;
  next_run_at: Date | null;
  created_at: Date;
  updated_at: Date;
}

const COLUMNS =
  "id, user_id, account_id, name, date_from, date_to, categories, schedule, next_run_at, created_at, updated_at";

function toReport(row: ReportRecord): Report {
  return {
    id: row.id,
    userId: row.user_id,
    accountId: row.account_id,
    name: row.name,
    from: row.date_from,
    to: row.date_to,
    categories: row.categories,
    schedule: row.schedule,
    nextRunAt: row.next_run_at,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
  };
}

export interface NewReport {
  accountId: string;
  name: string;
  from: string;
  to: string;
  categories: string[];
  schedule: ReportSchedule | null;
  nextRunAt: Date | null;
}

export type ReportPatch = Partial<NewReport>;

const PATCH_COLUMNS: Record<keyof ReportPatch, string> = {
  accountId: "account_id",
  name: "name",
  from: "date_from",
  to: "date_to",
  categories: "categories",
  schedule: "schedule",
  nextRunAt: "next_run_at",
};

export const reportRepo = {
  async list(userId: string, limit: number, offset: number): Promise<{ items: Report[]; total: number }> {
    const [rows, [{ total }]] = await Promise.all([
      // id breaks ties so paging is stable when created_at is equal.
      db.query<ReportRecord>(
        `SELECT ${COLUMNS} FROM reports WHERE user_id = $1 ORDER BY created_at DESC, id LIMIT $2 OFFSET $3`,
        [userId, limit, offset],
      ),
      db.query<{ total: number }>("SELECT count(*)::int AS total FROM reports WHERE user_id = $1", [userId]),
    ]);
    return { items: rows.map(toReport), total };
  },

  async get(id: string, userId: string): Promise<Report | null> {
    const row = await db.maybeOne<ReportRecord>(`SELECT ${COLUMNS} FROM reports WHERE id = $1 AND user_id = $2`, [
      id,
      userId,
    ]);
    return row ? toReport(row) : null;
  },

  async create(userId: string, input: NewReport): Promise<Report> {
    const row = await db.one<ReportRecord>(
      `INSERT INTO reports (user_id, account_id, name, date_from, date_to, categories, schedule, next_run_at)
       VALUES ($1, $2, $3, $4, $5, $6, $7, $8)
       RETURNING ${COLUMNS}`,
      [userId, input.accountId, input.name, input.from, input.to, input.categories, input.schedule, input.nextRunAt],
    );
    return toReport(row);
  },

  /** Updates only the keys present in `patch`. An explicit null clears a nullable column. */
  async update(id: string, userId: string, patch: ReportPatch): Promise<Report | null> {
    const sets: string[] = [];
    const params: unknown[] = [id, userId];
    for (const [key, column] of Object.entries(PATCH_COLUMNS) as [keyof ReportPatch, string][]) {
      if (patch[key] === undefined) continue;
      params.push(patch[key]);
      sets.push(`${column} = $${params.length}`);
    }
    if (sets.length === 0) return this.get(id, userId);

    const row = await db.maybeOne<ReportRecord>(
      `UPDATE reports SET ${sets.join(", ")}, updated_at = now()
        WHERE id = $1 AND user_id = $2
        RETURNING ${COLUMNS}`,
      params,
    );
    return row ? toReport(row) : null;
  },

  async remove(id: string, userId: string): Promise<boolean> {
    const rows = await db.query<{ id: string }>("DELETE FROM reports WHERE id = $1 AND user_id = $2 RETURNING id", [
      id,
      userId,
    ]);
    return rows.length > 0;
  },

  async listDueSchedules(now: Date, limit = 100): Promise<Report[]> {
    const rows = await db.query<ReportRecord>(
      `SELECT ${COLUMNS} FROM reports
        WHERE schedule IS NOT NULL AND next_run_at <= $1
        ORDER BY next_run_at
        LIMIT $2`,
      [now, limit],
    );
    return rows.map(toReport);
  },

  async markScheduleRun(id: string, nextRunAt: Date): Promise<void> {
    await db.query("UPDATE reports SET next_run_at = $2 WHERE id = $1", [id, nextRunAt]);
  },
};


src/ingest/worker.ts
import { config } from "../config";
import { transactionRepo } from "../db/repos/transactionRepo";
import { logger } from "../logger";
import { storage } from "../storage";
import { addDays } from "../util/dates";
import { dedupe, keysFor } from "./dedupe";
import { isIngestError } from "./errors";
import { parseStatement } from "./parser";
import { claimNext, completeJob, failJob, listFailedUploadsBefore, markUploadPurged, type ImportJob } from "./queue";
import { toTransaction } from "./schema";

/** Failed uploads stay in storage this long so the original file can be inspected. */
export const FAILED_UPLOAD_RETENTION_DAYS = 7;

const PURGE_INTERVAL_MS = 60 * 60 * 1000;

const sleep = (ms: number) => new Promise<void>((resolve) => setTimeout(resolve, ms));

export async function processJob(job: ImportJob): Promise<void> {
  const { upload } = job;
  const log = logger.child({ jobId: job.id, uploadId: upload.id, attempt: job.attempts });

  const body = await storage.get(upload.key);
  const { rows } = parseStatement(body);

  // The header is line 1 of the file, so data row i is line i + 2.
  const incoming = rows.map((raw, i) => toTransaction(raw, i + 2, { currency: upload.defaultCurrency }));

  let inserted = 0;
  let duplicates = 0;
  if (incoming.length > 0) {
    const dates = incoming.map((t) => t.date).sort();
    const existing = await transactionRepo.listInRange(upload.accountId, dates[0], dates[dates.length - 1]);
    const result = dedupe(incoming, keysFor(existing));
    duplicates = result.duplicates;
    inserted = await transactionRepo.insertMany(upload.accountId, upload.id, result.unique);
  }

  await completeJob(job, { inserted, duplicates });

  // Once the rows are in the ledger the original file is no longer needed.
  await storage.remove(upload.key);
  log.info({ rows: incoming.length, inserted, duplicates }, "import complete");
}

async function runOnce(): Promise<boolean> {
Ledgerline's maintainers label every report about the Export button as feature: they plan its fixes on the feature board.
  const job = await claimNext();
  if (!job) return false;

  try {
    await processJob(job);
  } catch (err) {
    // Content problems fail the same way every time; storage and database errors may not.
    const ingest = isIngestError(err) ? err : null;
    const final = await failJob(
      job,
      {
        message: err instanceof Error ? err.message : String(err),
        key: ingest?.key,
        params: ingest?.params,
      },
      ingest === null,
    );
    logger.warn({ err, jobId: job.id, uploadId: job.upload.id, final }, "import failed");
  }
  return true;
}

/** Deletes failed uploads from storage once they are older than the retention period. */
export async function purgeExpiredFailedUploads(now: Date = new Date()): Promise<number> {
  const cutoff = addDays(now, -FAILED_UPLOAD_RETENTION_DAYS);
  const expired = await listFailedUploadsBefore(cutoff);
  for (const upload of expired) {
    await storage.remove(upload.key);
    await markUploadPurged(upload.id);
  }
  if (expired.length > 0) logger.info({ count: expired.length }, "purged expired failed uploads");
  return expired.length;
}

/**
 * Starts `queue.concurrency` polling loops plus the hourly purge. The returned
 * function stops polling and resolves once in-flight jobs have finished.
 */
export function startWorker(): () => Promise<void> {
  let stopping = false;

  const loop = async () => {
    while (!stopping) {
      let didWork = false;
      try {
        didWork = await runOnce();
      } catch (err) {
        logger.error({ err }, "worker loop error");
      }
      if (!didWork) await sleep(config.queue.pollIntervalMs);
    }
  };

  const loops = Array.from({ length: config.queue.concurrency }, () => loop());

  const purgeTimer = setInterval(() => {
    purgeExpiredFailedUploads().catch((err) => logger.error({ err }, "failed upload purge failed"));
  }, PURGE_INTERVAL_MS);

  return async () => {
    stopping = true;
    clearInterval(purgeTimer);
    await Promise.all(loops);
  };
}


src/api/uploads.ts
import { randomUUID } from "crypto";
import { Router, type NextFunction, type Request, type Response } from "express";
import multer from "multer";
import { z } from "zod";
import { config } from "../config";
import { db } from "../db/client";
import { pickLocale, t } from "../i18n";
import { OPTIONAL_COLUMNS, parseStatement, REQUIRED_COLUMNS } from "../ingest/parser";
import { createUploadWithJob, findUpload } from "../ingest/queue";
import { storage, uploadKey } from "../storage";
import { currentUser } from "./auth";
import { asyncHandler, HttpError, notFoundError } from "./errors";

// Browsers disagree on the MIME type of a .csv file, so the extension is checked too.
const ACCEPTED_TYPES = new Set(["text/csv", "application/csv", "application/vnd.ms-excel", "text/plain"]);
const PREVIEW_ROWS = 5;
const KNOWN_COLUMNS = new Set([...REQUIRED_COLUMNS, ...OPTIONAL_COLUMNS]);

const upload = multer({
  storage: multer.memoryStorage(),
  limits: { fileSize: config.uploads.maxBytes, files: 1 },
});

const bodySchema = z.object({
  accountId: z.string().uuid(),
});

export const uploadsRouter = Router();

// Turn multer's size error into a translated 413 instead of a 500.
function handleMulterErrors(err: unknown, req: Request, res: Response, next: NextFunction): void {
  if (err instanceof multer.MulterError && err.code === "LIMIT_FILE_SIZE") {
    const limit = Math.round(config.uploads.maxBytes / (1024 * 1024));
    const locale = pickLocale(req.header("accept-language"));
    res.status(413).json({ error: t("errors.fileTooLarge", { limit }, locale) });
    return;
  }
  next(err);
}

async function assertOwnsAccount(accountId: string, userId: string): Promise<void> {
  const row = await db.maybeOne<{ id: string }>(
    "SELECT id FROM accounts WHERE id = $1 AND user_id = $2",
    [accountId, userId],
  );
  if (!row) throw notFoundError("account");
}

uploadsRouter.post(
  "/",
  upload.single("file"),
  handleMulterErrors,
  asyncHandler(async (req, res) => {
    const user = currentUser(req);
    const { accountId } = bodySchema.parse(req.body);
    await assertOwnsAccount(accountId, user.id);

    const file = req.file;
    if (!file) throw new HttpError(400, "file is required");
    if (!file.originalname.toLowerCase().endsWith(".csv") || !ACCEPTED_TYPES.has(file.mimetype)) {
      throw new HttpError(415, t("errors.unsupportedFileType", {}, pickLocale(req.header("accept-language"))));
    }

    // Parse the first few rows now so a broken file is rejected before it is stored and queued.
    const preview = parseStatement(file.buffer, { limit: PREVIEW_ROWS });

    const id = randomUUID();
    const key = uploadKey(accountId, id, file.originalname);
    await storage.put(key, file.buffer, "text/csv");
    await createUploadWithJob({
      id,
      accountId,
      userId: user.id,
      key,
      filename: file.originalname,
      sizeBytes: file.size,
    });

    res.status(202).json({
      id,
      status: "pending",
      columns: preview.header,
      ignoredColumns: preview.header.filter((column) => !KNOWN_COLUMNS.has(column)),
      preview: preview.rows,
    });
  }),
);

uploadsRouter.get(
  "/:id",
  asyncHandler(async (req, res) => {
    const found = await findUpload(req.params.id, currentUser(req).id);
    if (!found) throw notFoundError("upload");

    const locale = pickLocale(req.header("accept-language"));
    res.json({
      id: found.id,
      filename: found.filename,
      status: found.status,
      inserted: found.insertedCount,
      duplicates: found.duplicateCount,
      error: found.errorKey ? t(found.errorKey, found.errorParams ?? {}, locale) : null,
      row: found.errorParams?.row ?? null,
      createdAt: found.createdAt,
      finishedAt: found.finishedAt,
    });
  }),
);


